        "resources": ["m", "cv", "ready"],
        "functions": ["main", "waiter", "notifier"]
      },
      "requires": {
        "resources": [],
        "functions": []
      },
      "resources": [
        {"name": "m", "kind": "sync", "type": "Mutex", "mode": "Sync"},
        {"name": "cv", "kind": "sync", "type": "Condvar", "mode": "Sync"},
        {"name": "ready", "kind": "var", "type": "Var", "base": "Bool", "init": false}
      ],
      "protection": [
        {"var": "ready", "lock": "m"}
      ],
      "functions": [
        {
          "name": "main",
          "kind": "normal",
          "body": [
            {"sid": "s1", "kind": "scope", "funcs": ["main::waiter", "main::notifier"]},
            {"sid": "s2", "kind": "return"}
          ]
        },
        {
          "name": "waiter",
          "kind": "normal",
          "form": "closure",
          "body": [
            {"sid": "s1", "kind": "mutex_lock", "resource": "main::m"},
            {"sid": "s2", "kind": "condvar_wait", "condvar": "main::cv", "lock": "main::m"},
            {"sid": "s3", "kind": "mutex_unlock", "resource": "main::m"},
            {"sid": "s4", "kind": "return"}
          ]
        },
        {
          "name": "notifier",
          "kind": "normal",
          "form": "closure",
          "body": [
            {"sid": "s1", "kind": "mutex_lock", "resource": "main::m"},
            {"sid": "s2", "kind": "write_shared", "resource": "main::ready", "expr": "true"},
            {"sid": "s3", "kind": "condvar_notify", "condvar": "main::cv"},
            {"sid": "s4", "kind": "mutex_unlock", "resource": "main::m"},
            {"sid": "s5", "kind": "return"}
          ]
        }
      ]
    }
  ]
}
</previous_candidate>

